  "implementation": "def solve(case):
    kept_indices = []
    token_labels = []
    for indices, label in zip(case['word_token_indices'], case['word_labels']):
        if label:
            kept_indices.extend(indices)
            token_labels.extend([label] * len(indices))
    return {"kept_indices": kept_indices, "token_labels": token_labels}"
